// Streaming RPC-specific client options
package client

import (
	"context"
	"fmt"
	"time"

	"github.com/cloudwego/kitex/internal/client"
	"github.com/cloudwego/kitex/pkg/endpoint/cep"
	"github.com/cloudwego/kitex/pkg/endpoint/sep"
	"github.com/cloudwego/kitex/pkg/utils"
)

// WithStreamOptions wraps stream-specific options into a general Option.
func WithStreamOptions(opts ...StreamOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamOptions(%d options)", len(opts)))
		for _, opt := range opts {
			opt.F(o, di)
		}
	}}
}

// WithStreamRecvTimeout specifies the timeout for stream receive operations.
// This is the timeout for each individual Recv() call on a stream.
func WithStreamRecvTimeout(d time.Duration) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamRecvTimeout(%dms)", d.Milliseconds()))
		o.StreamX.RecvTimeout = d
	}}
}

// WithStreamRecvMiddleware adds middleware for stream receive operations.
func WithStreamRecvMiddleware(mw cep.StreamRecvMiddleware) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamRecvMiddleware(%+v)", utils.GetFuncName(mw)))
		mwb := func(ctx context.Context) cep.StreamRecvMiddleware {
			return mw
		}
		o.StreamRecvMWBs = append(o.StreamRecvMWBs, mwb)
	}}
}

// WithStreamRecvMiddlewareBuilder adds a middleware builder for stream receive operations.
func WithStreamRecvMiddlewareBuilder(mwb cep.StreamRecvMiddlewareBuilder) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamRecvMiddlewareBuilder(%+v)", utils.GetFuncName(mwb)))
		o.StreamRecvMWBs = append(o.StreamRecvMWBs, mwb)
	}}
}

// WithStreamSendMiddleware adds middleware for stream send operations.
func WithStreamSendMiddleware(mw sep.StreamSendMiddleware) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamSendMiddleware(%+v)", utils.GetFuncName(mw)))
		mwb := func(ctx context.Context) sep.StreamSendMiddleware {
			return mw
		}
		o.StreamSendMWBs = append(o.StreamSendMWBs, mwb)
	}}
}

// WithStreamSendMiddlewareBuilder adds a middleware builder for stream send operations.
func WithStreamSendMiddlewareBuilder(mwb sep.StreamSendMiddlewareBuilder) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamSendMiddlewareBuilder(%+v)", utils.GetFuncName(mwb)))
		o.StreamSendMWBs = append(o.StreamSendMWBs, mwb)
	}}
}
