// connError returns ConnectionError(code) but first
// stashes away a public reason to the caller can optionally relay it
// to the peer before hanging up on them. This might help others debug
// their implementations.
// Enhanced with frame context for better diagnostics.
func (fr *Framer) connError(code http2.ErrCode, reason string) error {
	// Add frame context if available
	var contextMsg string
	if fr.lastFrame != nil {
		fh := fr.lastFrame.Header()
		contextMsg = fmt.Sprintf(" [last_frame: type=%s stream_id=%d length=%d flags=0x%x]",
			fh.Type, fh.StreamID, fh.Length, fh.Flags)
	}
	if fr.lastHeaderStream != 0 {
		contextMsg += fmt.Sprintf(" [pending_header_stream=%d]", fr.lastHeaderStream)
	}

	fr.errDetail = errors.New(reason + contextMsg)
